body.script:
function nmaPermitChange(v){
    ['printing','trading','text','regulatory'].forEach(function(t){
        var el=document.getElementById('fields_'+t);
        if(el) el.style.display=v===t?'block':'none';
    });
    var amounts={'printing':'210.00','trading':'210.00','text':'210.00','regulatory':'1,210.00'};
    var amt=document.getElementById('nma_total_amt');
    if(amt) amt.textContent=(amounts[v]||'210.00')+' ⓘ';
}
function nmaPubTypeChange(v, prefix){
    ['book','map','brochures','movie'].forEach(function(t){
        var el=document.getElementById(prefix+'_'+t);
        if(el) el.style.display=v===t?'block':'none';
    });
}
function nmaSubjCatChange(v, prefix){
    ['general_knowledge','philosophy','religions','social_science'].forEach(function(t){
        var el=document.getElementById(prefix+'_sub_'+t);
        if(el) el.style.display=v===t?'flex':'none';
    });
}
function nmaMaterialTypeChange(v){
    document.getElementById('reg_book').style.display=v==='book'?'block':'none';
    document.getElementById('reg_brochures').style.display=v==='brochures_catalogs'?'block':'none';
}

function nmaFileSelected(input, key){
    if(input.files && input.files[0]){
        var fname = input.files[0].name;
        document.getElementById('uploaded_'+key).style.display='flex';
        document.getElementById('name_'+key).textContent=fname;
        document.getElementById('box_'+key).style.borderColor='#1abc9c';
        var err=document.getElementById('err_'+key);
        if(err) err.style.display='none';
    }
}
function nmaRemoveFile(key){
    document.getElementById('uploaded_'+key).style.display='none';
    document.getElementById('box_'+key).style.borderColor='#ccc';
    var inp=document.querySelector('#box_'+key+' input[type=file]');
    if(inp) inp.value='';
}
